import { computed, Injectable, signal } from '@angular/core';

export interface Track {
  title: string;
  artist: string;
  link: string;
  cover: string;
}

@Injectable({
  providedIn: 'root',
})
export class AudioService {
  private audio = new Audio();

  // Signals for reactive state management
  playlist = signal<Track[]>([]);
  currentIndex = signal<number>(0);
  isPlaying = signal<boolean>(false);
  currentTime = signal<number>(0);
  duration = signal<number>(0);

  // Computed state
  currentTrack = computed(() => this.playlist()[this.currentIndex()]);
  progress = computed(() => this.duration() ? (this.currentTime() / this.duration()) * 100 : 0);

  constructor() {
    this.setupAudioListeners();
  }

  setPlaylist(tracks: Track[]) {
    this.playlist.set(tracks);
    if (tracks.length > 0) {
      this.loadTrack(0);
    }
  }

  private setupAudioListeners() {
    this.audio.addEventListener('timeupdate', () => this.currentTime.set(this.audio.currentTime));
    this.audio.addEventListener('durationchange', () => this.duration.set(this.audio.duration || 0));
    this.audio.addEventListener('ended', () => this.next());

    // Add this diagnostic error listener
    this.audio.addEventListener('error', (e) => {
      const error = this.audio.error;
      console.error('Angular Audio Player Error Context:', {
        code: error?.code,
        message: error?.message,
        attemptedSrc: this.audio.src
      });

      this.isPlaying.set(false);

      // Friendly status message handling
      if (error?.code === 4) {
        alert(`Failed to load audio. Please verify that "${this.currentTrack()?.link}" exists.`);
      }
    });
  }

  loadTrack(index: number) {
    this.currentIndex.set(index);
    const track = this.currentTrack();
    if (track) {
      console.log(track)
      this.audio.src = track.link;
      this.audio.load();
      if (this.isPlaying()) this.audio.play();
    }
  }

  togglePlay() {
    if (this.isPlaying()) {
      this.audio.pause();
      this.isPlaying.set(false);
    } else {
      this.audio.play();
      this.isPlaying.set(true);
    }
  }

  seek(percent: number) {
    const time = (percent / 100) * this.duration();
    this.audio.currentTime = time;
    this.currentTime.set(time);
  }

  next() {
    const nextIndex = (this.currentIndex() + 1) % this.playlist().length;
    this.loadTrack(nextIndex);
  }

  prev() {
    const prevIndex = this.currentIndex() === 0 ? this.playlist().length - 1 : this.currentIndex() - 1;
    this.loadTrack(prevIndex);
  }
}
