import { Component, OnInit, signal } from '@angular/core';
import { MultimediaService } from '../multimediaservice/multimedia.service';

@Component({
  selector: 'app-multimedialist',
  standalone: false,
  templateUrl: './multimedialist.component.html',
  styleUrls: ['./multimedialist.component.css']
})
export class MultimedialistComponent implements OnInit {

  isLoading = signal<boolean>(false);
  item = signal<any>({});

  constructor(
    private _multimediaService:MultimediaService
  ) { }

  ngOnInit() {
    this.isLoading.set(true);
    this._multimediaService.getMultimediaItem()
    .subscribe(
      (data)=>{ console.log(data)
        this.item.set(data);
        this.isLoading.set(false);
      }
    )
  }

}
